WITH valid_products AS (SELECT * FROM products WHERE product_name LIKE '%Sho%'), launch_month_summary AS (SELECT MONTH(launch_date) AS launch_month, ROUND(STDDEV(cost), 2) AS stddev_cost, MIN(launch_date) AS first_launch_date FROM valid_products GROUP BY MONTH(launch_date)) SELECT * FROM launch_month_summary WHERE stddev_cost >= 51 ORDER BY first_launch_date, launch_month LIMIT 10;
